// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Private_Bank c;
    Receiver caller;

    function setUp() public {
        c = new Private_Bank(address(new Log()));
        caller = new Receiver();
    }

    function testFuzz_property(uint256 deposit, uint256 amount) public {
        vm.assume(deposit <= VALUE_CAP);
        // admissible domain: a deposit strictly above MinDeposit, and a partial/strict
        // withdrawal (1 <= amount <= deposit) that succeeds for the reference
        deposit = bound(deposit, c.MinDeposit() + 1, 1000 ether);
        amount = bound(amount, 1, deposit);

        vm.deal(address(caller), deposit);
        vm.prank(address(caller));
        c.Deposit{value: deposit}();

        vm.prank(address(caller));
        c.CashOut(amount);

        // RULE: after a successful partial withdrawal of `amount` from a balance of
        // `deposit`, the caller's balance is exactly deposit - amount.
        assertTrue(c.balances(address(caller)) == deposit - amount);
    }
}

contract Receiver {
    receive() external payable {}
}
